# 数据文件：src/components/permissions/BashPermissionRequest/BashPermissionRequest.tsx
# slug = src_components_permissions_BashPermissionRequest_BashPermissionRequest_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是 Bash 工具执行前的权限确认弹窗，也是整个权限体系里最复杂的一块门面。结构分三层：最外层是分流器（先判断这条命令能不能交给专门的 sed 编辑弹窗处理，不能才进主体）；中间是 Inner 主体（约 535 行，负责所有状态与选项组装）；最上面被单独提出去的是分类器检查字幕（一个 20fps 的微光动画，必须隔离，理由见下面那段注释）。整份文件最值得读的是「选项集合如何随特性开关与后端建议变形」这一条主线。'''),
    (36, 'before', '''这段注释是本次阅读最有价值的一处工程记录：微光时钟原本住在 Inner 主体内部，而 Inner 里有一个 Compiler 的 bailout（编译器放弃自动记忆化），于是每 50 毫秒的一次时钟跳动都会把整棵 JSX 树（Dialog 加 Select 加全部子节点）重建一遍，分类器检查平均要 1 到 3 秒，换算下来就是几十次全量重建。修法不是优化时钟，而是把时钟搬到一个极小的独立组件里——让高频更新的边界收缩到一个只渲染一行文字的盒子里。'''),
    (42, 'before', '''隔离出来的字幕组件：只做一件事——把待检查文本逐字符包上微光字符，按当前光带位置上色。它自身重渲染不会波及父级，因为父级传给它的只有静态文本。'''),
    (54, 'before', '''逐字符渲染：先把字符串拆成字符数组并缓存起来（这句展开只在首次执行），之后每次光带移动只重建渲染节点、不重建数据。这是本文件里唯一的高频路径，所以每一步缓存都值得。'''),
    (71, 'before', '''分流器：把工具输入按 Bash 的输入结构解析出命令与描述，再看这条命令是不是 sed 编辑命令。是就整单交给 SedEditPermissionRequest（那边有专门的编辑预览与差异界面），不是才进主体。分流放在最外层而不是 Inner 内部，是为了让两条路径各自拥有独立的状态与钩子，互不牵连。'''),
    (84, 'before', '''解析结果与 sed 判定一起放进同一个缓存槽：只要工具输入引用不变，就不再重复解析。这里缓存的是「命令文本、描述、sed 信息」三元组，后面的早退判断与主体初始化都直接读它们。'''),
    (89, 'before', '''sed 判定只需要一次：把命令文本交给解析器，返回非空就说明这是一条可以按行编辑语义来展示的命令。注意判定在缓存槽内完成，意味着弹窗存活期间不会重算。'''),
    (135, 'before', '''主体只在非 MCP 的普通命令上被调用——因为 MCP 工具走的是另一套确认界面，那套没有命令文本、没有沙箱、也没有分类器。这条注释解释了为什么下面这么长的组件敢直接假定「命令一定存在」。'''),
    (136, 'before', '''主体签名：先继承通用的权限请求属性（确认句柄、上下文、完成与拒绝回调、详细模式、协作徽章），再补上分流器已经解析好的命令与描述。命令是必填、描述可选，因为描述可能由分类器异步补出来。'''),
    (151, 'before', '''解释器状态：把工具名、工具输入、工具描述、对话消息一起交出去，换来一个可见性开关、一份解释内容的异步承诺、以及一个是否可用的标志。这套状态由 hooks 统一维护，主体只负责在界面上给它让出位置。'''),
    (170, 'before', '''反馈模式钩子一次性交回十个成员，分成四组：两种输入模式（同意时带指令、拒绝时带指令）、两个「曾进入过反馈模式」的标记（用于埋点区分纯点击与真的输入过）、两份反馈正文与其写入口、当前聚焦的选项、以及三个事件处理（切换输入模式、执行拒绝、聚焦变化）。把这些从主体里抽走，是因为它们要同时被选项组装、键盘接管、埋点三处使用。'''),
    (176, 'before', '''调试面板开关：默认关闭，由键绑定翻转。打开后弹窗下半部分整个换成权限决策的调试信息，是排查「为什么这条命令被允许或拒绝」的主要入口。'''),
    (180, 'before', '''这个布尔量记录的是「挂载时描述是否为空」这一事实，并且一旦收到非空描述就永久置假。它存在的意义是让选项文案能区分「本来就有描述」与「描述是刚补出来的」两种情况——后者需要给用户一个提示，告诉他马上会自动填入一条规则。'''),
    (183, 'before', '''异步补描述：仅当分类器权限开启时才发请求。用 AbortController 做取消，组件卸载即中止；请求失败被静默吞掉并保留原描述，因为补描述只是锦上添花，失败不该弹错误。注意成功分支里还顺手把「初始为空」标记清掉。'''),
    (195, 'before', '''这段是本文件第二个高价值注释，讲的是一个真实的产品事故：对于复合命令（先切目录、再查状态、再跑测试这种用与号串起来的写法），后端已经用语法树切开、逐个做了权限检查、给出了正确的按子命令建议；但界面下方的同步前缀启发式只认整串命令的前两个词，于是会造出永远匹配不上的死规则，用户配置里越积越多。所以这里按「决策原因是否为子命令结果」来识别复合命令，一旦识别出来就绕开同步启发式。'''),
    (209, 'before', '''复合命令判定：决策原因是子命令结果即视为复合。这个布尔量后面有三处用途——决定是否跳过异步精化、决定可编辑前缀的初值来源、以及决定选项集合走哪条分支。'''),
    (219, 'before', '''可编辑前缀的状态用惰性初始化器，而不是在渲染体里直接算：前缀提取要做正则与切分，如果写在渲染体里，每次重渲染都会重跑一遍，而它其实只在首次需要。注释还说明了另一层原因——语法树支持在外部构建里是被编译期开关关掉的，异步精化路径会恒返回空数组，所以这个同步初值才是普通用户真正看到的东西，必须足够好。'''),
    (233, 'before', '''用户是否手动改过前缀。这个引用存在的唯一目的是防止竞态：异步精化的结果回来时，如果用户已经自己敲过字，就不能覆盖他的输入。用引用而不是状态，是因为它只在回调里被读，不需要触发重渲染。'''),
    (238, 'before', '''异步精化：复合命令直接跳过（后端建议已经是权威）。其余情况把命令交给静态前缀提取器，并把「这段子命令是否只读」作为判断依据传进去，得到前缀链后只取第一段拼成规则内容。三重放弃条件：已取消、用户已编辑、提取结果为空——任一成立就保持同步初值不动。'''),
    (261, 'before', '''「分类器是否曾经在检查中」只取挂载时的快照，不随后续变化。注释解释了为什么不需要闩锁：这个标志在入队时被置真，之后只会由真转假一次，所以拿到初值就够了。另外注意条件表达式的写法——特性开关在这里的作用是让属性读取本身在外部构建里被消除，而不是单纯地短路求值。'''),
    (269, 'before', '''这一组派生值全部只依赖工具输入（弹窗存活期间不变）。注释再次提到微光时钟曾经住在这里、并且编译器无法为导入函数做记忆化，所以这里的记忆化是人工兜底：即便别处有重渲染源，这三个判断也不会重算。三者分别是破坏性命令警告、沙箱是否启用、本次是否真的会被沙箱包裹。'''),
    (289, 'before', '''选项集合的组装是这个文件的枢纽：它把后端建议、决策原因、两份反馈写入口、分类器描述与其初值、已有的允许描述、两种输入模式、可编辑前缀与其写入口，一共十二个输入交给选项工厂，产出的数组直接喂给下拉框。所有会变的输入都列在依赖里，所以选项文案能随用户输入实时变形（比如把前缀嵌进选项标题）。'''),
    (308, 'before', '''调试面板的键绑定：只在确认这类上下文里生效。处理函数用函数式更新翻转，避免把当前值放进依赖导致回调频繁重建。'''),
    (320, 'before', '''选项选中处理是这个文件最长的一段，分四段：先做埋点用的序号映射，再处理两个特殊选项（编辑前缀、分类器复核），最后落到常规三选项的开关。读的时候要盯住一件事——每个分支都自己调一次记录函数再自己调完成回调，没有统一的收尾，所以漏调就是漏埋点。'''),
    (322, 'before', '''序号映射：埋点只接受数字不接受字符串，所以要把选项值翻成序号。注意这里有两套映射，默认四档，分类器开启时多一档（分类器复核插在拒绝前面，于是拒绝从第三档挪到第四档）。这种「同一份语义两套编号」的写法会让历史数据在同一指标下不可比，属于典型的埋点债。'''),
    (342, 'before', '''编辑前缀分支：取用户改过的前缀，去空白后为空就当作纯同意、不带任何规则更新；非空则造一条允许规则，规则内容是前缀本身，落盘目标是本地设置——这一步就是「以后这类命令别再问我」的实现。完成后立即返回，不落进下面的常规开关。'''),
    (362, 'before', '''分类器复核分支：这里落的是分类器生成的描述，规则内容要经过一次转换（把自然语言描述转成规则内容的形式），落盘目标是会话级而不是本地设置——因为这条规则是由模型描述推导出来的，可信度低于用户亲手编辑的前缀，所以只在本次会话有效。这个差异是本文件最容易被忽略的设计细节。'''),
    (427, 'before', '''字幕的嵌套三元是整个状态机的摘要，按优先级从高到低：已自动批准就显示带对勾的成功字幕（若命中规则再附规则名）；正在检查就显示微光字幕；曾经检查过但当前不在检查，说明检查已完成却没自动批准，显示需要人工批准；从未检查过就什么都不显示。四层都套在特性开关里，外部构建恒为空。'''),
    (435, 'before', '''弹窗标题会随沙箱状态变化：沙箱启用但本次命令不会被沙箱包裹时，标题加上未沙箱化的后缀——这是给用户的一个明确警示，因为接下来的命令会直接作用于真实文件系统。'''),
    (450, 'before', '''调试分支：上半部分换成权限决策调试信息，工具名写死为 Bash，所以不可达规则的过滤范围也被限定在 Bash 上。只有在详细调试模式下才额外提示如何关闭这个面板，否则用户会以为界面卡住了。'''),
    (456, 'before', '''常规分支：先是权限规则解释（把决策原因翻成人话），再是破坏性命令警告（自动批准时压暗，因为此时已经不需要用户做决定），然后才是询问句与下拉框。'''),
    (466, 'before', '''自动批准时把每个选项都标成禁用并把整个下拉框置为禁用，而不是换一套静态文案——这样布局高度不变，界面不会因为状态切换而跳动。注意这里对选项做的是浅拷贝加禁用标记，原始选项数组仍然被缓存。'''),
]
